const media={rosa:{src:'photos/rosa.webp',source:'https://rosakhutor.ru/maps/',credit:'Роза Хутор · rosakhutor.ru'},polyana:{src:'photos/polyana.webp',source:'https://krasnayapolyanaresort.ru/',credit:'Риксос · Курорт Красная Поляна'},volen:{src:'photos/volen.webp',source:'https://volen.ru/',credit:'Волен · volen.ru'}};
const escapeText=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function enhanceCatalog(){for(const card of $$('.resortcard')){const r=media[card.dataset.id];if(!r)continue;const art=card.querySelector('.cardart');art.style.backgroundImage=`url('${r.src}')`;art.classList.add('realphoto');art.setAttribute('role','img');art.setAttribute('aria-label','Фотография: '+r.credit);art.querySelector('.artnum').textContent='РЕАЛЬНОЕ МЕСТО'} }
