const cover=document.createElement('article');cover.className='snowcover';cover.innerHTML='<img id="coverphoto" src="photos/rosa.webp" alt="Реальный вид курорта Роза Хутор"><div class="coverveil"></div><div class="covercontent"><span class="glasspill">ГОРА. ЛЮДИ. ТВОЯ ИСТОРИЯ.</span><h2>Встретимся<br>на высоте.</h2><p>Найди свой склон. И тех, кто разделит этот момент.</p><button class="glasscta" id="findcrew">Найти компанию <span>↗</span></button></div><button id="photocredit" class="photocredit">Фото: Роза Хутор ↗</button>';$('.locationbar').before(cover);$('#findcrew').onclick=()=>go('crew');
const oldSelectResort=selectResort;selectResort=function(id){oldSelectResort(id);const m=media[selected.id];if(m){$('#coverphoto').src=m.src;$('#coverphoto').alt='Реальный вид: '+selected.name;$('#photocredit').textContent='Фото: '+m.credit+' ↗'}else{$('#coverphoto').src='photos/rosa.webp';$('#coverphoto').alt='Роза Хутор';$('#photocredit').textContent='Фото: Роза Хутор ↗'}};
$('#photocredit').onclick=()=>{const r=media[selected.id]||media.rosa;modal(`<span class="eyebrow">ИСТОЧНИК ИЗОБРАЖЕНИЯ</span><h2>${r.credit}</h2><p>Реальное изображение из открытого материала сайта курорта. Используется для закрытой демонстрации. Лицензия на публичное коммерческое использование не подтверждена; перед публичным выпуском нужна проверка прав.</p><p><a href="${r.source}" target="_blank" rel="noopener noreferrer">Открыть первоисточник ↗</a></p>`)};
const shortcuts=document.createElement('div');shortcuts.className='servicestrip';shortcuts.innerHTML='<button id="openrent"><span>◒</span><strong>Прокат</strong><small>Лыжи и сноуборд</small></button><button id="openchat"><span>◌</span><strong>Чаты</strong><small>Свои на склоне</small></button><button id="openpartners"><span>◇</span><strong>Для курортов</strong><small>Партнёрская модель</small></button>';cover.after(shortcuts);
let purpose='ride',peopleRegion='all',liked=read('snow-liked',[]),blocked=read('snow-blocked',[]),messages=read('snow-messages',{});
const companions=[{id:'alina',name:'Алина',age:28,letter:'А',resort:'Роза Хутор',region:'sochi',sport:'Сноуборд',level:'Уверенно',bio:'Первый подъём, свежий снег и кофе после. Ищу компанию без гонки за рекордами.',tone:'peach'},{id:'max',name:'Макс',age:32,letter:'М',resort:'Шерегеш',region:'siberia',sport:'Лыжи',level:'Средний',bio:'За красивые спуски и разговоры на подъёмнике. Вместе выбирать маршрут интереснее.',tone:'blue'},{id:'nika',name:'Ника',age:27,letter:'Н',resort:'Сорочаны',region:'moscow',sport:'Сноуборд',level:'Начинаю',bio:'Учусь поворачивать и не бояться. Буду рада спокойной компании на склоне.',tone:'green'}];
$('#socialhub').innerHTML='<div class="socialheading"><span class="eyebrow">ХИМИЯ НА ОДНОЙ ВЫСОТЕ</span><h1>Твои люди.<br><em>Твоя стихия.</em></h1><p>Один интерес - тысячи поводов познакомиться.</p></div><div class="socialtabs"><button data-purpose="ride" class="active">Покататься вместе</button><button data-purpose="date">Знакомства 18+</button><button id="mychats">Чаты</button></div><div class="peoplefilters"><label>Направление<select id="peopleregion"><option value="all">Все направления</option><option value="sochi">Сочи</option><option value="moscow">Подмосковье</option><option value="siberia">Шерегеш</option></select></label><span class="demochip">ДЕМО-АНКЕТЫ</span></div><div id="peoplegrid" class="peoplegrid"></div><p class="socialnote">Анкеты вымышлены. Приглашения и сообщения сохраняются только в этом браузере. Реальные люди их не получают.</p>';
function renderPeople(){const list=companions.filter(p=>!blocked.includes(p.id)&&(peopleRegion==='all'||peopleRegion===p.region));$('#peoplegrid').innerHTML=list.length?list.map(p=>`<article class="personcard ${p.tone}"><div class="personvisual"><span class="personinitial">${p.letter}</span><span class="personbadge">${p.sport} · ${p.level}</span><span class="fictional">Иллюстрация · демо</span></div><div class="personinfo"><h2>${p.name}, ${p.age}</h2><span class="personplace">${p.resort}</span><p>${p.bio}</p><div class="personactions"><button class="primary" data-like="${p.id}">${liked.includes(p.id)?'♥ Приглашение сохранено':purpose==='date'?'♡ Познакомиться':'＋ Позвать кататься'}</button><button class="outline" data-chat="${p.id}" aria-label="Демо-чат с ${p.name}">Чат</button></div><button class="reportlink" data-report="${p.id}">Пожаловаться / скрыть</button></div></article>`).join(''):'<div class="empty">Пока никого в этом направлении. Выбери другое или проверь скрытые анкеты в настройках.</div>';$$('[data-like]').forEach(b=>b.onclick=()=>{const id=b.dataset.like;liked=liked.includes(id)?liked.filter(x=>x!==id):[...liked,id];write('snow-liked',liked);renderPeople();toast('Изменение сохранено локально. Приглашение не отправлено.')});$$('[data-chat]').forEach(b=>b.onclick=()=>openChat(b.dataset.chat));$$('[data-report]').forEach(b=>b.onclick=()=>reportPerson(b.dataset.report))}
$$('[data-purpose]').forEach(b=>b.onclick=()=>{const set=()=>{purpose=b.dataset.purpose;$$('[data-purpose]').forEach(x=>x.classList.toggle('active',x===b));renderPeople()};if(b.dataset.purpose==='date'){modal('<span class="eyebrow">ЗНАКОМСТВА 18+</span><h2>Начнём с уважения.</h2><p>Раздел предназначен для совершеннолетних. Не публикуй точные координаты, документы и платёжные данные. Встречу планируй в людном месте на курорте. Это демо, реальные знакомства пока не доступны.</p><button class="primary" id="adultconfirm">Мне есть 18 лет · посмотреть демо</button>');$('#adultconfirm').onclick=()=>{set();$('#modal').close()}}else set()});$('#peopleregion').onchange=e=>{peopleRegion=e.target.value;renderPeople()};
function chatList(){modal('<span class="eyebrow">ТВОЯ КОМПАНИЯ</span><h2>Чаты на высоте.</h2><div class="settingslist">'+companions.filter(p=>!blocked.includes(p.id)).map(p=>`<button data-conversation="${p.id}">${p.name} · ${p.resort} <small>Демо</small></button>`).join('')+'</div><p>Локальная демонстрация интерфейса. Сообщения никому не отправляются.</p>');$$('[data-conversation]').forEach(b=>b.onclick=()=>openChat(b.dataset.conversation))}
function openChat(id){const person=companions.find(p=>p.id===id);if(!person||blocked.includes(id))return;modal(`<div class="chatheader"><span class="avatar">${person.letter}</span><div><h2>${person.name}</h2><small>Демо-чат · не в сети</small></div></div><div id="chatmessages" class="chatmessages" aria-live="polite"></div><form id="chatcompose" class="chatcompose"><input id="chatinput" maxlength="1000" autocomplete="off" aria-label="Сообщение" placeholder="Напиши первое «привет»"><button type="submit" aria-label="Сохранить демо-сообщение">↑</button></form><p class="socialnote">Только на твоём устройстве. Доставки и автоматических ответов нет.</p>`);const paint=()=>{$('#chatmessages').innerHTML=(messages[id]||[]).map(m=>`<div class="messagebubble">${escapeText(m.text)}<small>${new Date(m.at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})} · локально</small></div>`).join('')||'<div class="chatempty">Общий склон - уже повод начать разговор.</div>';$('#chatmessages').scrollTop=$('#chatmessages').scrollHeight};paint();$('#chatcompose').onsubmit=e=>{e.preventDefault();const text=$('#chatinput').value.trim();if(!text)return;messages[id]=[...(messages[id]||[]),{text,at:Date.now()}].slice(-100);write('snow-messages',messages);$('#chatinput').value='';paint()}}
function reportPerson(id){modal('<h2>Комфорт важнее всего.</h2><p>В демо можно скрыть анкету локально. Жалоба не отправляется модератору: сервер модерации ещё не подключён.</p><label>Причина<select class="reasonselect"><option>Нежелательное общение</option><option>Подозрительная анкета</option><option>Нарушение правил</option></select></label><button class="primary" id="hideperson">Скрыть демо-анкету</button>');$('#hideperson').onclick=()=>{blocked=[...new Set([...blocked,id])];write('snow-blocked',blocked);$('#modal').close();renderPeople();toast('Анкета скрыта на этом устройстве')}}
$('#mychats').onclick=chatList;$('#openchat').onclick=chatList;
function rental(){modal('<span class="eyebrow">ПУТЕШЕСТВУЙ НАЛЕГКЕ</span><h2>Твоя экипировка.<br>На нужной высоте.</h2><p>Собери список для проката. Это план поездки, не бронирование: наличие и стоимость подтверждает выбранный пункт.</p><form id="rentalform" class="rentalform"><label>Курорт<select id="rentalresort">'+resorts.map(r=>`<option value="${r.id}" ${r.id===selected.id?'selected':''}>${r.name}</option>`).join('')+'</select></label><label>Комплект<select id="rentaltype"><option>Лыжи + ботинки + палки</option><option>Сноуборд + ботинки</option><option>Шлем</option></select></label><label>Дата<input id="rentaldate" type="date" required></label><label>Дней<input id="rentaldays" type="number" value="1" min="1" max="30" required></label><button class="primary" type="submit">Сохранить план проката</button></form><p>Перед арендой уточни: размер и посадку ботинок, ростовку, состояние креплений, залог, документы, стоимость повреждений и условия возврата. Тарифы и наличие в приложении пока не подключены.</p><div id="rentalresult" aria-live="polite"></div>');const date=new Date();$('#rentaldate').min=date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0');$('#rentaldate').value=$('#rentaldate').min;$('#rentalform').onsubmit=e=>{e.preventDefault();const r=resorts.find(x=>x.id===$('#rentalresort').value);const plan={resort:r.name,type:$('#rentaltype').value,date:$('#rentaldate').value,days:Number($('#rentaldays').value),demo:true};write('snow-rental',plan);$('#rentalresult').innerHTML=`<p class="savedplan">✓ План сохранён: ${escapeText(plan.resort)}, ${escapeText(plan.type)}, ${plan.date}, ${plan.days} дн.</p><p><a href="${r.url}" target="_blank" rel="noopener noreferrer">Уточнить прокат на сайте курорта ↗</a></p>`}}
$('#openrent').onclick=rental;
function partners(){modal('<span class="eyebrow">SnowWow ДЛЯ БИЗНЕСА</span><h2>Встретим гостей<br>вместе.</h2><p>Концепция партнёрства: подтверждённая карточка курорта, обновление статусов трасс, прокат, инструкторы и предложения гостям.</p><div class="partnersteps"><div><b>01</b><span>Карточка и права на медиа</span></div><div><b>02</b><span>Источник актуальных статусов</span></div><div><b>03</b><span>Условия бронирования и комиссии</span></div><div><b>04</b><span>Договор, ответственность и поддержка</span></div></div><p>Договоры с представленными курортами не заключены. Карточка в каталоге не означает партнёрство. Платёж и подписание документов здесь не доступны.</p><button class="primary" id="partnerbrief">Скачать структуру партнёрского предложения</button>');$('#partnerbrief').onclick=()=>{const body='SnowWow / Структура партнёрского предложения\n\nСтатус: концепция для переговоров, не договор и не оферта.\n\n1. Стороны и полномочия подписантов.\n2. Разрешение на название, фото, карты и обновление контента.\n3. Проверка статусов трасс и время обновления.\n4. Каталог проката, инструкторов, услуги и наличие.\n5. Переходы, промокоды, атрибуция заказов, комиссия и возвраты.\n6. Персональные данные: роли сторон, основания, хранение и передача.\n7. Поддержка, претензии, ответственность, срок и расторжение.\n8. Подписи и реквизиты после согласования.\n';const url=URL.createObjectURL(new Blob([body],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='SnowWow_partner_brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}$('#openpartners').onclick=partners;
const originalSettings=settings;settings=function(){originalSettings();const list=$('.settingslist');const b=document.createElement('button');b.textContent='Прокат и план экипировки';b.onclick=rental;list.prepend(b);const p=document.createElement('button');p.textContent='Для курортов и партнёров';p.onclick=partners;list.prepend(p);const reset=document.createElement('button');reset.textContent='Показать скрытые демо-анкеты';reset.onclick=()=>{blocked=[];write('snow-blocked',[]);renderPeople();toast('Скрытые анкеты снова доступны')};list.append(reset)};$('#open-settings').onclick=()=>settings();
